import json, os, re, socket, sys, time, urllib.error, urllib.request
mode = os.environ.get("EXT_MODE", "good"); start = os.environ["AFD_START_URL"]; task = os.environ["AFD_TASK"]
op = urllib.request.build_opener(urllib.request.ProxyHandler({}))
def call(method, url, body=None):
    req = urllib.request.Request(url, data=json.dumps(body).encode() if body is not None else None, method=method, headers={"Content-Type": "application/json"})
    try:
        with op.open(req, timeout=30) as r: return r.status, json.loads(r.read() or b"null")
    except urllib.error.HTTPError as e: return e.code, None
    except OSError: return 0, None
if mode == "timeout": time.sleep(120)
if mode == "containment":
    def tcp(h, p):
        try: socket.create_connection((h, p), 3).close(); return "OPEN"
        except Exception as e: return "blocked:" + type(e).__name__
    res = {"afd-proxy:8080": tcp("afd-proxy", 8080), "app:8080": tcp("app", 8080), "1.1.1.1:443": tcp("1.1.1.1", 443), "10.232.0.2:8080 (gateway)": tcp("10.232.0.2", 8080)}
    print("AFD_RESULT_JSON=" + json.dumps({"claimed_success": False, "summary": json.dumps(res)})); sys.exit(0)
item = (re.findall(r"'([^']+)'", task) or ["order"])[0]
st, doc = call("POST", start, {"item": item})
ok = 200 <= st < 300
if not ok:                                   # uncertain: read back once, never resubmit
    time.sleep(2); st2, doc2 = call("GET", start)
    ok = st2 == 200 and any(o.get("item") == item for o in (doc2 or []))
summary = f"POST -> {st}; claimed {'success' if ok else 'failure'}"
if mode == "missing": print(summary); sys.exit(0)
if mode == "malformed": print("AFD_RESULT_JSON={claimed_success: maybe"); sys.exit(0)
if mode == "exitcode": print(summary); sys.exit(0 if ok else 3)
print("AFD_RESULT_JSON=" + json.dumps({"claimed_success": ok, "summary": summary}))
